        const stableDrift=Math.sin((state.matchTime||0)*.31+(e.flowPhase||0))*.012;
        const y=e.y+stableDrift+(pressure<.13?evadeSign*(.035+.018*(a.turn||.8)):0);
        const advance=counter?.15:finalAttack?.095:.065;
